import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

public final class Money {
    private final long cents;
    private final String currency;

    public Money(long cents, String currency) {
        this.cents = cents;
        this.currency = Objects.requireNonNull(currency);
    }

    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Money other)) return false;
        return cents == other.cents && currency.equals(other.currency);
    }

    @Override public int hashCode() {
        return Objects.hash(cents, currency);      // same fields as equals.
    }

    public static void main(String[] args) {
        Money a = new Money(500, "USD"), b = new Money(500, "USD");
        System.out.println((a == b) + " " + a.equals(b));   // false true
        Set<Money> set = new HashSet<>();
        set.add(a); set.add(b);
        System.out.println(set.size() + " " + set.contains(new Money(500, "USD")));   // 1 true
    }
}
```

| Contract | Means |
|---|---|
| reflexive. | a.equals(a). |
| symmetric. | a.equals(b) iff b.equals(a). |
| transitive and consistent. | stable, chainable answers. |
| hashCode agreement. | a.equals(b) implies equal hash codes. |

